import{_ as l,o as i,c as e,a3 as t}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"安裝 Ollama","description":"Windows / macOS / Linux 安裝 Ollama，開啟 OpenAI 兼容 API（11434），供 MiniTavern 手機局域網連接本地大模型。","frontmatter":{"title":"安裝 Ollama","description":"Windows / macOS / Linux 安裝 Ollama，開啟 OpenAI 兼容 API（11434），供 MiniTavern 手機局域網連接本地大模型。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"安裝 Ollama · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Windows / macOS / Linux 安裝 Ollama，開啟 OpenAI 兼容 API（11434），供 MiniTavern 手機局域網連接本地大模型。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/ollama/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/ollama/install"}]]},"headers":[],"relativePath":"zh-TW/ollama/install.md","filePath":"zh-TW/ollama/install.md","lastUpdated":1787224147000}'),s={name:"zh-TW/ollama/install.md"};function n(o,a,r,p,h,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="安裝-ollama" tabindex="-1">安裝 Ollama <a class="header-anchor" href="#安裝-ollama" aria-label="Permalink to &quot;安裝 Ollama&quot;">​</a></h1><p>Ollama 在電腦上運行模型，並提供 <strong>OpenAI 兼容</strong> 的 HTTP API（默認端口 <code>11434</code>）。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>打開官網 <a href="https://ollama.com/download" target="_blank" rel="noreferrer">https://ollama.com/download</a>，下載 Windows 安裝包。</li><li>安裝並啟動 Ollama（托盤區應出現圖標）。</li><li>打開 <strong>命令提示符</strong> 或 <strong>PowerShell</strong>，執行：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>能輸出版本號即安裝成功。</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><ol><li>從 <a href="https://ollama.com/download" target="_blank" rel="noreferrer">https://ollama.com/download</a> 下載 macOS 版並拖入「應用程序」。</li><li>首次打開允許網絡權限。</li><li>打開「終端」：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="驗證本機-api" tabindex="-1">驗證本機 API <a class="header-anchor" href="#驗證本機-api" aria-label="Permalink to &quot;驗證本機 API&quot;">​</a></h2><p>服務啟動後，在電腦瀏覽器打開：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:11434</span></span></code></pre></div><p>或終端：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:11434/api/tags</span></span></code></pre></div><p>能返回 JSON（模型列表，可能為空）說明 API 已監聽。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./models">下載與選擇模型</a></li><li><a href="./lan">開啟局域網訪問</a>（手機連電腦必做）</li></ul>',17)])])}const u=l(s,[["render",n]]);export{m as __pageData,u as default};
